// Validate Input node
const body = $input.first().json.body || $input.first().json;

const errors = [];
const email = (body.email || '').trim();
const message = (body.message || '').trim();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!email) {
  errors.push('email alanı zorunludur.');
} else if (!emailRegex.test(email)) {
  errors.push('email formatı geçersiz.');
}

if (!message) {
  errors.push('message alanı zorunludur.');
} else if (message.length < 10) {
  errors.push('message çok kısa, anlamlı bir lead extraction için yetersiz.');
}

const isValid = errors.length === 0;
const domain = email.includes('@') ? email.split('@')[1] : null;

return [{
  json: {
    is_valid: isValid,
    errors,
    normalized: {
      company_name: (body.company_name || '').trim() || null,
      contact_name: (body.contact_name || '').trim() || null,
      email: email || null,
      domain,
      phone: (body.phone || '').trim() || null,
      message: message || null,
      source_channel: body.source_channel || 'web_form',
      received_at: new Date().toISOString()
    }
  }
}];

// Build LLM Request node
const n = $json.normalized;

const systemPrompt = `You are a lead-qualification extraction assistant for a B2B infrastructure/telecom sales pipeline. Given a raw inbound lead message (which may be in Turkish or English), extract structured information and return ONLY valid JSON (no markdown, no explanation, no code fences) matching EXACTLY this schema:

{
  "company_name": string or null,
  "industry": string or null,
  "project_type": string or null,
  "company_size": "small" | "medium" | "enterprise" | "unknown",
  "budget_range": "low" | "medium" | "high" | "unknown",
  "urgency": "immediate" | "this_quarter" | "exploring",
  "timeline": string or null,
  "requirements": string (concise summary, max 2 sentences),
  "confidence_score": number between 0 and 1
}

Rules:
- confidence_score reflects how certain you are overall, based on how explicit the message is.
- company_size: infer from contextual clues. Use "unknown" if no signal exists.
- If budget or timeline are not mentioned, use "unknown" / null and lower confidence_score accordingly.
- Do not invent facts not implied by the message.
- Respond with raw JSON only, nothing else.`;

const userPrompt = `Company name hint (may be empty): ${n.company_name || 'unknown'}
Lead message:
"""
${n.message}
"""`;

return [{
  json: {
    llm_request: {
      model: 'llama3.1:8b',
      stream: false,
      format: 'json',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    },
    normalized: n
  }
}];

// Parse AI Output node
const response = $input.first().json;
let extracted;
let parseError = null;

try {
  const content = response.message?.content || response.response || '';
  extracted = JSON.parse(content);
} catch (e) {
  parseError = e.message;
  extracted = {
    company_name: null,
    company_size: 'unknown',
    industry: null,
    project_type: null,
    budget_range: 'unknown',
    urgency: 'exploring',
    timeline: null,
    requirements: null,
    confidence_score: 0
  };
}

// Deterministik confidence hesaplama.
// llama3.1:8b'nin kendi bildirdigi confidence_score guvenilmez bulundu:
// uc bagimsiz denemede, mesaj ne kadar net olursa olsun hep ~0.8'de sikisti.
// Bunun yerine confidence, extraction'da kac alanin gercekten doldugunun
// (null/unknown kalmadigi) oranindan hesaplaniyor - modelin oznel yargisina
// degil, cikan verinin somut tamligina dayanan bir olcum.
const fieldsToCheck = [
  'company_name',
  'industry',
  'project_type',
  'company_size',
  'budget_range',
  'urgency',
  'timeline',
  'requirements'
];

const unfilledValues = new Set([null, undefined, '', 'unknown']);

let filledCount = 0;
for (const field of fieldsToCheck) {
  if (!unfilledValues.has(extracted[field])) {
    filledCount++;
  }
}

let confidence = parseError ? 0 : filledCount / fieldsToCheck.length;
confidence = Math.max(0, Math.min(1, confidence));

const normalized = $('Build LLM Request').first().json.normalized;

return [{
  json: {
    normalized,
    extraction: {
      ...extracted,
      confidence_score: confidence,
      // debug/karsilastirma icin LLM'in kendi bildirdigi degeri ayri tutuyoruz
      llm_reported_confidence: typeof extracted.confidence_score === 'number' ? extracted.confidence_score : null
    },
    needs_human_review: confidence < 0.75 || !!parseError,
    parse_error: parseError
  }
}];

