// Load Scoring Config node
// scoring_rules tablosundan gelen aktif kurallari 'Fetch Scoring Rules' node'undan okuyor,
// eksik/olmayan kural icin hardcoded default'a duser. product_fit keyword listesi
// DB semasinda yok, o yuzden hala koddan geliyor.
// response_target: bu execution'in yaniti kime donecek? 'browser' (reviewer form'u onayladiysa)
// ya da 'api' (orijinal webhook caller'i, ya otomatik onay ya da hic review gerekmedi).
const prior = $('Parse AI Output').first().json;

let responseTarget = 'api';
try {
  const decision = $('Approval Decision').first().json.Decision;
  if (decision === 'Approve') responseTarget = 'browser';
} catch (e) {
  responseTarget = 'api';
}

const rows = $input.all().map(item => item.json);

const defaults = {
  budget: { max_points: 30, weights: { high: 30, medium: 15, low: 5, unknown: 0 } },
  urgency: { max_points: 20, weights: { immediate: 20, this_quarter: 10, exploring: 3, unknown: 8 } },
  company_size: { max_points: 20, weights: { enterprise: 20, medium: 12, small: 5, unknown: 8 } },
  product_fit: { max_points: 30, weights: { exact_match: 30, partial_match: 15, poor_match: 0, unknown: 12 } }
};

const config = {
  budget: { max_points: defaults.budget.max_points, weights: { ...defaults.budget.weights } },
  urgency: { max_points: defaults.urgency.max_points, weights: { ...defaults.urgency.weights } },
  company_size: { max_points: defaults.company_size.max_points, weights: { ...defaults.company_size.weights } },
  product_fit: {
    max_points: defaults.product_fit.max_points,
    weights: { ...defaults.product_fit.weights },
    keywords: {
      exact: ['fiber', 'fiber optic', 'fiber optik', 'altyapı', 'infrastructure', 'network buildout', 'omurga', 'backbone'],
      partial: ['telecom', 'telekom', 'network', 'connectivity', 'bağlantı', 'kablo']
    }
  },
  version: 'v1'
};

for (const row of rows) {
  const key = row.rule_name;
  if (config[key] && row.weight_config) {
    config[key].weights = { ...config[key].weights, ...row.weight_config };
  }
}
if (rows.length && rows[0].version) {
  config.version = rows[0].version;
}

return [{ json: { ...prior, scoring_config: config, response_target: responseTarget } }];

// Calculate Lead Score node
const extraction = $json.extraction;
const config = $json.scoring_config;

const budgetKey = extraction.budget_range || 'unknown';
const budgetScore = config.budget.weights[budgetKey] ?? 0;

const urgencyKey = extraction.urgency || 'exploring';
const urgencyScore = config.urgency.weights[urgencyKey] ?? 0;

const sizeKey = extraction.company_size || 'unknown';
const companyScore = config.company_size.weights[sizeKey] ?? 0;

const searchText = `${extraction.project_type || ''} ${extraction.requirements || ''}`.toLowerCase();
const { exact, partial } = config.product_fit.keywords;

let fitLevel = 'poor_match';
if (exact.some(kw => searchText.includes(kw))) {
  fitLevel = 'exact_match';
} else if (partial.some(kw => searchText.includes(kw))) {
  fitLevel = 'partial_match';
}
const fitScore = config.product_fit.weights[fitLevel];

const totalScore = budgetScore + urgencyScore + companyScore + fitScore;

return [{
  json: {
    ...$json,
    lead_score: {
      budget_score: budgetScore,
      urgency_score: urgencyScore,
      company_score: companyScore,
      fit_score: fitScore,
      fit_level: fitLevel,
      total_score: totalScore,
      scoring_version: config.version
    }
  }
}];

